BEGIN;
CREATE TABLE IF NOT EXISTS "facilities" ("facility_id" TEXT PRIMARY KEY, "lat" DOUBLE PRECISION, "lon" DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS "stock" ("id" INTEGER PRIMARY KEY, "facility_id" TEXT, "commodity" TEXT, "month" TEXT, "opening" INTEGER, "received" INTEGER, "wastage" INTEGER, "consumed" INTEGER, "closing" INTEGER, "reported_stockout_days" INTEGER);
CREATE TABLE IF NOT EXISTS "orders" ("id" INTEGER PRIMARY KEY, "facility_id" TEXT, "commodity" TEXT, "month" TEXT, "cutoff_date" DATE, "order_date" DATE, "qty_requested" INTEGER, "qty_delivered" INTEGER, "delivery_month" TEXT);
CREATE TABLE IF NOT EXISTS "payments" ("id" INTEGER PRIMARY KEY, "month" TEXT, "county_arrears_flag" INTEGER, "amount_owed_kes" BIGINT);
COMMIT;
